            transliteration = "Allāhumma ihdinī li-aḥsani al-akhlāq, lā yahdī li-aḥsanihā illā anta, waṣrif ʿannī sayyiʾahā, lā yaṣrifu ʿannī sayyiʾahā illā anta.",
