    private val byMonthDay: Map<Pair<Int, Int>, DailyDua> =
        all.associateBy { it.hijriMonth to it.hijriDay }

    /** Returns the dua for a Hijri date, or null if not yet in the catalogue. */
    fun forDate(hijriMonth: Int, hijriDay: Int): DailyDua? =
        byMonthDay[hijriMonth to hijriDay]
}
